-- MogHub Logbook: your progress in FINAL FANTASY RESONANCE in one screen with its own main-menu entry (one of
-- MogHub's spare rows): treasure chests and item spots per area, side quests, Colosseum battles and tablet shards. Read-only: it
-- asks the game through its own functions and conditions (Scripts/progress.lua) and never changes your save.
-- The game data it lists (IDs, conditions, string keys) is generated by tools/export_data.py.
local mod, kit = ...
local view = require("view")

local cfg = mod:settings{
    { key = "ShowContents", label = "Show what's left to find", type = "toggle", default = true,
      help = "In an area's list, unopened chests and item spots not picked up yet show what they hold. Off: they show ??? until you find them." },
    { key = "ShowLocked", label = "Show quests not available yet", type = "toggle", default = true,
      help = "Side quests that open later in the story are listed by name. Off: they show as ???." },
}

local function settings() view.showContents, view.showLocked = cfg.ShowContents, cfg.ShowLocked end

local screen = mod:screen{
    title = "Logbook",
    opened = function(host, u) settings(); view.open(host, u) end,
    poll = function() settings(); view.poll() end,
    closed = function() view.close() end,
    confirm = function() view.confirm() end,
}
if not screen then mod:log("no free main-menu entry: the Logbook can't be opened") end
